    private List<Shipment>? shipments;
    private string filterText = string.Empty;
    private string statusFilter = string.Empty;

    private IEnumerable<Shipment> FilteredShipments => (shipments ?? [])
        .Where(s => string.IsNullOrEmpty(filterText) ||
                    s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
                    s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase))
        .Where(s => string.IsNullOrEmpty(statusFilter) ||
                    s.Status.ToString() == statusFilter);

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task AdvanceStatus(Shipment shipment)
    {
        var next = shipment.Status switch
        {
            ShipmentStatus.Pending => ShipmentStatus.PickedUp,
            ShipmentStatus.PickedUp => ShipmentStatus.InTransit,
            ShipmentStatus.InTransit => ShipmentStatus.OutForDelivery,
            ShipmentStatus.OutForDelivery => ShipmentStatus.Delivered,
            _ => shipment.Status
        };
        await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, next);
        shipment.Status = next;
    }

    private async Task MarkException(Shipment shipment)
    {
        await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, ShipmentStatus.Exception);
        shipment.Status = ShipmentStatus.Exception;
    }

