@page "/"
@inject IShipmentService ShipmentService
@inject NavigationManager Navigation
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services

<PageTitle>ShipmentTracker - Home</PageTitle>

<div class="container">
    <h1 class="mb-4">Shipment Tracker</h1>
    <p class="lead">Track your shipments in real time. Enter your tracking number below to get started.</p>

    <div class="card mb-4">
        <div class="card-body">
            <h5 class="card-title">Track a Shipment</h5>
            <div class="input-group">
                <input type="text" class="form-control" placeholder="Enter tracking number (e.g., TRK-001)"
                       @bind="trackingNumber" @bind:event="oninput" @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary" @onclick="TrackShipment" disabled="@string.IsNullOrWhiteSpace(trackingNumber)">
                    Track
                </button>
            </div>
            @if (searchPerformed && trackedShipment is null)
            {
                <div class="alert alert-warning mt-3">No shipment found with that tracking number.</div>
            }
        </div>
    </div>

    @if (trackedShipment is not null)
    {
        <div class="card mb-4 border-success">
            <div class="card-header bg-success text-white">
                <strong>Shipment @trackedShipment.TrackingNumber</strong>
            </div>
            <div class="card-body">
                <div class="row">
                    <div class="col-md-6">
                        <p><strong>Status:</strong> <span class="badge @GetStatusBadgeClass(trackedShipment.Status)">@trackedShipment.Status</span></p>
                        <p><strong>Origin:</strong> @trackedShipment.Origin</p>
                        <p><strong>Destination:</strong> @trackedShipment.Destination</p>
                    </div>
                    <div class="col-md-6">
                        <p><strong>Recipient:</strong> @trackedShipment.RecipientName</p>
                        <p><strong>Shipped:</strong> @trackedShipment.ShippedDate.ToString("MMM dd, yyyy")</p>
                        <p><strong>Estimated Delivery:</strong> @trackedShipment.EstimatedDelivery.ToString("MMM dd, yyyy")</p>
                    </div>
                </div>
            </div>
        </div>
    }

    <AuthorizeView>
        <Authorized>
            <p>Welcome back! <a href="/shipments">View all shipments</a> or <a href="/shipments/new">create a new one</a>.</p>
        </Authorized>
        <NotAuthorized>
            <p><a href="Account/Login">Log in</a> to manage shipments as a dispatcher.</p>
        </NotAuthorized>
    </AuthorizeView>
</div>

@code {
    private string trackingNumber = string.Empty;
    private Shipment? trackedShipment;
    private bool searchPerformed;

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        searchPerformed = true;
        trackedShipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-info text-dark",
        ShipmentStatus.OutForDelivery => "bg-primary",
        ShipmentStatus.PickedUp => "bg-secondary",
        ShipmentStatus.Exception => "bg-danger",
        _ => "bg-warning text-dark"
    };
}

