@page "/shipments"
@attribute [Authorize]
@inject IShipmentService ShipmentService
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services

<PageTitle>All Shipments - ShipmentTracker</PageTitle>

<div class="container">
    <div class="d-flex justify-content-between align-items-center mb-4">
        <h1>Shipments</h1>
        <a href="/shipments/new" class="btn btn-primary">+ New Shipment</a>
    </div>

    <div class="row mb-3">
        <div class="col-md-4">
            <input type="text" class="form-control" placeholder="Filter by destination..."
                   @bind="filterText" @bind:event="oninput" />
        </div>
        <div class="col-md-3">
            <select class="form-select" @bind="statusFilter">
                <option value="">All Statuses</option>
                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                {
                    <option value="@status">@status</option>
                }
            </select>
        </div>
    </div>

    @if (shipments is null)
    {
        <p><em>Loading shipments...</em></p>
    }
    else if (!FilteredShipments.Any())
    {
        <div class="alert alert-info">No shipments found.</div>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead class="table-dark">
                    <tr>
                        <th>Tracking #</th>
                        <th>Destination</th>
                        <th>Recipient</th>
                        <th>Status</th>
                        <th>Est. Delivery</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var shipment in FilteredShipments)
                    {
                        <tr>
                            <td><strong>@shipment.TrackingNumber</strong></td>
                            <td>@shipment.Destination</td>
                            <td>@shipment.RecipientName</td>
                            <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                            <td>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                            <td>
                                <div class="btn-group btn-group-sm">
                                    @if (shipment.Status != ShipmentStatus.Delivered)
                                    {
                                        <button class="btn btn-outline-success" @onclick="() => AdvanceStatus(shipment)"
                                                title="Advance status">
                                            ▶
                                        </button>
                                    }
                                    @if (shipment.Status != ShipmentStatus.Exception)
                                    {
                                        <button class="btn btn-outline-danger" @onclick="() => MarkException(shipment)"
                                                title="Mark exception">
                                            ⚠
                                        </button>
                                    }
                                </div>
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
</div>

@code {
    private List<Shipment>? shipments;
    private string filterText = string.Empty;
    private string statusFilter = string.Empty;

    private IEnumerable<Shipment> FilteredShipments => (shipments ?? [])
        .Where(s => string.IsNullOrEmpty(filterText) ||
                    s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
                    s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase))
        .Where(s => string.IsNullOrEmpty(statusFilter) ||
                    s.Status.ToString() == statusFilter);

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task AdvanceStatus(Shipment shipment)
    {
        var next = shipment.Status switch
        {
            ShipmentStatus.Pending => ShipmentStatus.PickedUp,
            ShipmentStatus.PickedUp => ShipmentStatus.InTransit,
            ShipmentStatus.InTransit => ShipmentStatus.OutForDelivery,
            ShipmentStatus.OutForDelivery => ShipmentStatus.Delivered,
            _ => shipment.Status
        };
        await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, next);
        shipment.Status = next;
    }

    private async Task MarkException(Shipment shipment)
    {
        await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, ShipmentStatus.Exception);
        shipment.Status = ShipmentStatus.Exception;
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-info text-dark",
        ShipmentStatus.OutForDelivery => "bg-primary",
        ShipmentStatus.PickedUp => "bg-secondary",
        ShipmentStatus.Exception => "bg-danger",
        _ => "bg-warning text-dark"
    };
}

